use std::env;
use std::fs;
use std::process;
use std::collections::HashMap;

struct Section {
    name: String,
    keys: Vec<String>,
    values: HashMap<String, String>,
    inherits: Option<String>,
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("usage: {} <file>", args[0]);
        process::exit(1);
    }
    let content = fs::read_to_string(&args[1]).unwrap_or_else(|e| {
        eprintln!("error: {}", e);
        process::exit(1);
    });

    let mut sections: Vec<Section> = Vec::new();
    let mut current: Option<Section> = None;

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() { continue; }

        if line.starts_with('[') && line.ends_with(']') {
            if let Some(s) = current.take() {
                sections.push(s);
            }
            let name = line[1..line.len()-1].to_string();
            current = Some(Section {
                name,
                keys: Vec::new(),
                values: HashMap::new(),
                inherits: None,
            });
        } else if let Some(ref mut sec) = current {
            let parts: Vec<&str> = line.splitn(2, '=').collect();
            if parts.len() != 2 {
                eprintln!("malformed line: {}", line);
                process::exit(1);
            }
            let key = parts[0].trim().to_string();
            let val_raw = parts[1].trim();

            if key == "inherits" {
                let val = val_raw.trim_matches('"').to_string();
                sec.inherits = Some(val);
            } else {
                if sec.values.contains_key(&key) {
                    eprintln!("duplicate key '{}' in section '[{}]'", key, sec.name);
                    process::exit(1);
                }
                let val = val_raw.trim_matches('"').to_string();
                sec.keys.push(key.clone());
                sec.values.insert(key, val);
            }
        }
    }
    if let Some(s) = current.take() {
        sections.push(s);
    }

    let section_map: HashMap<String, usize> = sections.iter().enumerate()
        .map(|(i, s)| (s.name.clone(), i))
        .collect();

    for sec in &sections {
        let mut resolved_keys: Vec<String> = Vec::new();
        let mut resolved_values: HashMap<String, String> = HashMap::new();

        if let Some(ref parent_name) = sec.inherits {
            if let Some(&idx) = section_map.get(parent_name) {
                let parent = &sections[idx];
                for k in &parent.keys {
                    resolved_keys.push(k.clone());
                    resolved_values.insert(k.clone(), parent.values[k].clone());
                }
            }
        }

        for k in &sec.keys {
            if !resolved_values.contains_key(k) {
                resolved_keys.push(k.clone());
            }
            resolved_values.insert(k.clone(), sec.values[k].clone());
        }

        for k in &resolved_keys {
            println!("{}.{}={}", sec.name, k, resolved_values[k]);
        }
    }
}

