    let mut dry_run = false;
    let mut name: Option<String> = None;

    let mut i = 0;
    while i < rest.len() {
        match rest[i].as_str() {
            "--json" => {
                format = "json".to_string();
                i += 1;
            }
            "--format" => {
                i += 1;
                if i >= rest.len() {
                    eprintln!("--format requires a value");
                    process::exit(1);
                }
                format = rest[i].clone();
                i += 1;
            }
            "--dry-run" => {
                dry_run = true;
                i += 1;
            }
            s if s.starts_with('-') => {
                eprintln!("unknown option: {}", s);
                process::exit(1);
            }
            _ => {
                name = Some(rest[i].clone());
                i += 1;
            }
        }
    }

    let name = name.unwrap_or_else(|| {
        eprintln!("missing name argument");
        process::exit(1);
    });

    println!("{} name={} format={} dry_run={}", op, name, format, dry_run);
}
