            "name" => name = Some(parts[1].to_string()),
            "count" => {
                count = Some(parts[1].parse().unwrap_or_else(|_| {
                    eprintln!("invalid count: {}", parts[1]);
                    process::exit(1);
                }));
            }
            "note" => note = Some(parts[1].to_string()),
            other => {
                eprintln!("unknown field: {}", other);
                process::exit(1);
            }
        }
    }

    let name = name.unwrap_or_else(|| { eprintln!("missing name"); process::exit(1); });
    let count = count.unwrap_or_else(|| { eprintln!("missing count"); process::exit(1); });
    let note = note.unwrap_or_else(|| { eprintln!("missing note"); process::exit(1); });

    println!("{{\"count\":{},\"name\":\"{}\",\"note\":\"{}\"}}", count, json_escape(&name), json_escape(&note));
